import {
  Mesh,
  PlaneGeometry,
  Object3D,
  Vector3,
  Euler,
} from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Object} assets
 * @property {string} assets.imageUrl
 * @property {string} [assets.depthMapUrl]
 * @property {string} [assets.meshUrl]
 * @property {Object} placement
 * @property {Array<number>} placement.position
 * @property {Array<number>} placement.rotation
 * @property {Array<number>} placement.scale
 * @property {Object} visual
 * @property {Object} visual.colors
 * @property {Object} visual.typography
 * @property {string} visual.effects
 * @property {Object} textContent
 * @property {Array<string>} cinematicPrimitives
 * @property {Object} atlas
 * @property {number} atlas.region
 * @property {Array<number>} atlas.sourceRect
 */

/**
 * @typedef {Object} NodeContext
 * @property {{ load: (url: string) => any }} textureLoader
 * @property {{ load: (url: string) => any }} glbLoader
 * @property {{ [key: string]: Function }} primitives
 * @property {{ atlas: any }} fontAtlas
 */

export default function createNode(config, ctx) {
  // --- Geometry -------------------------------------------------------------
  const [x, y, z] = config.placement.position || [0, 0, 0];
  const [rx, ry, rz] = config.placement.rotation || [0, 0, 0];
  const [sx, sy, sz] = config.placement.scale || [1, 1, 1];

  // Use atlas source rect to compute aspect ratio for the plane
  const rect = config.atlas?.sourceRect || [0, 0, 512, 320];
  const width = rect[2];
  const height = rect[3];
  const aspect = width / height;

  const geometry = new PlaneGeometry(aspect, 1, 1, 1);
  geometry.scale(sx, sy, sz);

  // --- Texture ---------------------------------------------------------------
  const textureUrl = config.assets?.imageUrl;
  const tex = textureUrl ? ctx.textureLoader.load(textureUrl) : null;

  // --- Material ---------------------------------------------------------------
  const mat = new MeshBasicNodeMaterial({
    map: tex ? texture(tex) : null,
    transparent: true,
    depthWrite: true,
  });

  // --- Mesh ------------------------------------------------------------------
  const mesh = new Mesh(geometry, mat);
  mesh.position.copy(new Vector3(x, y, z));
  mesh.rotation.copy(new Euler(rx, ry, rz));

  // Attach empty handlers container
  mesh.userData.handlers = {};

  // Cleanup routine
  mesh.userData.cleanup = () => {
    geometry.dispose();
    mat.dispose();
    if (tex) tex.dispose();

    // Kill any GSAP timelines that might have been stored on the object
    if (mesh.userData._gsapTimelines) {
      mesh.userData._gsapTimelines.forEach((t) => t.kill());
      mesh.userData._gsapTimelines = null;
    }
  };

  // Apply cinematic primitives if any (none for this node, but keep generic)
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const name of config.cinematicPrimitives) {
      const primitive = ctx.primitives[name];
      if (typeof primitive === 'function') {
        primitive(mesh, {}); // params object left empty as spec provides none
      }
    }
  }

  // Return as generic Object3D (Mesh is already an Object3D)
  return mesh;
}
